-- Generated by scripts/generate-reporting-schema.mjs; contains no study data.
-- Apply with D1 migrations (one transaction). Do not split trigger bodies.
CREATE TABLE mirror_feed_state (
  singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
  feed_generation TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL
);

INSERT INTO mirror_feed_state VALUES (1, lower(hex(randomblob(16))), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));

ALTER TABLE mirror_changes ADD COLUMN record_json TEXT;

CREATE INDEX idx_mirror_generation_sequence ON mirror_changes(feed_generation, sequence);

CREATE UNIQUE INDEX idx_mirror_record_revision ON mirror_changes(feed_generation, dataset, record_id, revision);

CREATE TABLE nonparticipant_press_receipts (request_id TEXT PRIMARY KEY, button_id TEXT NOT NULL, created_at TEXT NOT NULL);

INSERT INTO mirror_changes (feed_generation, dataset, record_id, revision, operation, changed_at, record_json)
SELECT (SELECT feed_generation FROM mirror_feed_state WHERE singleton = 1), 'aqg_submissions', r.record_id, 1, 'upsert', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'),
       json_object('record_id', r.record_id, 'participant_id', r.participant_id, 'session_id', r.session_id, 'context_id', r.context_id, 'status', r.status, 'session_start', r.session_start, 'submitted_at', r.submitted_at, 'llm_product', r.llm_product, 'llm_model', r.llm_model, 'llm_description', r.llm_description, 'course_context', r.course_context, 'question_context', r.question_context, 'extra_instructions', r.extra_instructions, 'desired_questions', r.desired_questions, 'final_response', r.final_response, 'feedback_text', r.feedback_text, 'audio_object_key', r.audio_object_key, 'audio_duration_seconds', r.audio_duration_seconds, 'active_seconds', r.active_seconds, 'session_close_type', r.session_close_type, 'session_close_at', r.session_close_at, 'app_version', r.app_version, 'mode', r.mode, 'created_at', r.created_at)
FROM aqg_submissions r ORDER BY r.record_id;

