CREATE TRIGGER mirror_aqg_submissions_insert AFTER INSERT ON aqg_submissions
BEGIN
  INSERT INTO mirror_changes (feed_generation, dataset, record_id, revision, operation, changed_at, record_json)
  VALUES ((SELECT feed_generation FROM mirror_feed_state WHERE singleton = 1), 'aqg_submissions', NEW.record_id,
    (SELECT COALESCE(MAX(revision), 0) + 1 FROM mirror_changes
     WHERE feed_generation = (SELECT feed_generation FROM mirror_feed_state WHERE singleton = 1) AND dataset = 'aqg_submissions' AND record_id = NEW.record_id), 'upsert', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'),
